   +(today.length?'<div class="ld3-grid-3">'+today.map(function(l){return '<div class="ld3-summary"><div class="ld3-summary-label">'+esc(l.sourceType+' · '+l.status)+'</div><div class="ld3-summary-title">'+esc(l.company||l.contactName||'Unnamed lead')+'</div><div class="ld3-summary-copy">'+esc(l.nextStep||'Complete today’s prospecting touch.')+'</div><div class="ld3-mini-actions" style="justify-content:flex-start"><button class="ld3-mini-btn good" onclick="_rp2LeadsTouch(\''+encodeURIComponent(l.key)+'\')">Log touch</button><button class="ld3-mini-btn blue" onclick="_rp2LeadsSchedule(\''+encodeURIComponent(l.key)+'\')">Action Center</button></div></div>'}).join('')+'</div>':empty('No lead touches are due today','Schedule a concrete next touch for active prospects.'))
   +sectionHead('Lead source mix','Visible lead volume by source','Source counts do not imply quality; response, qualification, and conversion are shown separately.')
   +'<div class="ld3-panel"><div class="ld3-chart"><canvas id="ld3-chart"></canvas></div></div>'
